sop:
@n1 syntax.nominal head="line"
@c1 syntax.clause form=fragment modifier="solid" complement=$n1
@c2 syntax.clause form=imperative verb="flip" complement=$n2
@n2 syntax.nominal dependent="the" dependent="x" head="axis"

alt:
@n1 syntax.nominal dependent="line" head="solid"
@c1 syntax.clause form=imperative verb="flip" complement=$n2
@n2 syntax.nominal dependent="the" dependent="x" head="axis"
@c2 syntax.clause form=fragment complement=$n1
